import taf.rfrl.procedures.resources.python.admin_info_model.admin_info_model as admin_info_model
from copy import deepcopy
from random import randint
from taf.sbts.oam.coam.admin import admin
from taf.rfrl.procedures.resources.python.exceptions import ConnectionAliasNotProvided, RatTypeError, BbmodTypeError, \
    RatResetTypeError, RmodInfoNotFound


class RatResetEnvVerifier:

    def initialize(self, reset_rat, reset_type, connection_alias, called_cell_distnames=None):
        """
        Initialize the RAT reset environment verifier.
        """
        admin_base = _AdminBase(connection_alias=connection_alias)
        self._adm = admin_base._adm
        self._connection_alias = admin_base._connection_alias
        self._admin_bts_info_response = admin_base._admin_bts_info_response
        self.reset_rat = reset_rat
        self.reset_type = reset_type
        self.called_cell_distnames = called_cell_distnames
        self._all_bbmods = self._get_all_bbmods()
        self._all_cell_ids_per_rat = self._get_all_cell_ids_per_rat()
        self.affected_components = self._get_affected_components()
        self.not_affected_components = self._get_not_affected_components()
        _AdminBase.clear()

    @property
    def reset_rat(self):
        return self._reset_rat

    @reset_rat.setter
    def reset_rat(self, value):
        if value.lower() not in ['nr', 'lte', 'wcdma', 'gsm']:
            raise RatTypeError("Reset RAT must be one of 'nr', 'lte', 'wcdma', 'gsm'")
        self._reset_rat = value.lower()

    @property
    def reset_type(self):
        return self._reset_type

    @reset_type.setter
    def reset_type(self, value):
        if value.lower() not in ['soft', 'hard']:
            raise RatResetTypeError("RAT reset type must be either 'soft' or 'hard'")
        self._reset_type = value.lower()

    def get_affected_bbmod_ids(self):
        return [bbmod.configured_id for bbmod in self.affected_components['bbmods']]

    def get_affected_bbmod_ids_with_variant(self):
        return [(bbmod.configured_id, bbmod.status_variant) for bbmod in self.affected_components['bbmods']]

    def get_affected_bbmod_ids_online_variant(self):
        return [(bbmod.configured_id, 'online') for bbmod in self.affected_components['bbmods']]

    def get_not_affected_bbmod_ids_with_variant(self):
        return [(bbmod.configured_id, bbmod.status_variant) for bbmod in self.not_affected_components['bbmods']]

    def get_affected_rmod_ids(self):
        return [rmod.configured_id for rmod in self.affected_components['rmods']]

    def get_not_affected_rmod_ids(self):
        return [rmod.configured_id for rmod in self.not_affected_components['rmods']]

    def get_affected_cells_with_variant(self):
        return [(cell.configured_id, cell.type, cell.status_variant) for cell in self.affected_components['cells']]

    def get_affected_cells_online_variant(self):
        return [
            (cell.configured_id, cell.type,
             cell.status_variant if cell.status_variant == 'blocked' and cell.is_callable else 'online')
            for cell in self.affected_components['cells']
        ]

    def get_not_affected_cell_ids(self):
        return [(cell.configured_id, cell.type, cell.status_variant) for cell in self.not_affected_components['cells']]

    def get_not_affected_cells_distn(self):
        return [cell.distname for cell in self.not_affected_components['cells']]

    def get_random_callable_cell_distname(self):
        """
        Get the random 'configuration' distname of the callable cell.
        :return: 'configuration' distname of the callable cell. e.g. 'MRBTS-50612/NRBTS-50612/NRCELL-116'
                 if no callable cell found, return False.
        :rtype: Union[str, bool]
        """
        cells = self.get_callable_cell_distnames()
        return cells[randint(0, len(cells) - 1)] if cells else False

    def get_affected_rat_with_variant(self):
        return [(self.reset_rat, self.affected_components['rats'][self.reset_rat])]

    def get_not_affected_rats_with_variant(self):
        return [(rat, status) for rat, status in self.not_affected_components['rats'].items()]

    def get_affected_rats_online_variant(self):
        return [(rat, 'enabled') for rat, status in self.affected_components['rats'].items()]

    def get_rat_reset_cell_distnames(self):
        return [cell.distname for cell in self._get_all_cells_per_rat()[self.reset_rat]
                if self.called_cell_distnames is None or cell.distname in self.called_cell_distnames]

    def update_statuses_after_l3call_prep(self):
        return self._update_statuses_after_l3call_prep()

    def get_callable_cell_distnames(self):
        """
        Get the 'configuration' distnames of the callable cells.
        :return: 'configuration' distnames of the callable cells.
                  e.g. ['MRBTS-50612/NRBTS-50612/NRCELL-116', 'MRBTS-50612/NRBTS-50612/NRCELL-117']
        :rtype: list of str
        """
        return [cell.distname for cell in self._get_all_cells() if cell.is_callable]

    def _get_affected_components(self):
        affected_bbmods = self._get_affected_bbmods()
        affected_rmods = self._get_affected_rmods(affected_bbmods)
        affected_cells = self._get_affected_cells(affected_bbmods, affected_rmods)
        affected_rats = self._get_affected_rats(affected_cells)

        return {'bbmods': affected_bbmods, 'rmods': affected_rmods, 'cells': affected_cells, 'rats': affected_rats}

    def _get_not_affected_components(self):
        not_affected_components = {
            'bbmods': self._get_not_affected_bbmods(),
            'rmods': self._get_not_affected_rmods(),
            'cells': self._get_not_affected_cells(),
            'rats': self._get_not_affected_rats(),
        }
        return not_affected_components

    def _get_all_bbmods(self):
        infomodel_bbmods_info = self._adm.get_managed_objects('BBMOD_L', connection=self._connection_alias)
        api_bbmods_info = self._get_commissioned_bbmods(self._admin_bts_info_response['basebandModules'])
        return [_Bbmod(bbmod_info, infomodel_bbmods_info) for bbmod_info in api_bbmods_info]

    def _get_all_rmods(self):
        return list({port.connected_rmod for bbmod in self._all_bbmods for port in bbmod.connected_ports})

    def _get_all_cells(self):
        return list({cell for rmod in self._get_all_rmods() for cell in rmod.cells})

    def _get_all_cells_per_rat(self):
        cells_per_rat = {}
        all_cells = self._get_all_cells()

        for cell in all_cells:
            if cell.type not in cells_per_rat:
                cells_per_rat[cell.type] = []
            cells_per_rat[cell.type].append(cell)

        return cells_per_rat

    def _get_all_cell_ids_per_rat(self):
        return {rat: [cell.configured_id for cell in cells] for rat, cells in self._get_all_cells_per_rat().items()}

    def _get_affected_bbmods(self):
        affected_bbmods = set()

        if self.reset_type == 'soft':  # Soft RAT reset shouldn't affect BBMODs
            return []

        for bbmod in self._all_bbmods:
            if bbmod.type == 'ABIA':  # Hard RAT reset is not triggering ABIA reset
                continue

            configured_rats = [soc['configured_rats'] for soc in bbmod.socs_info]
            if all(self.reset_rat in rats for rats in configured_rats):
                bbmod.status_variant = 'initializing'
                affected_bbmods.add(bbmod)
            elif any(self.reset_rat in rats for rats in configured_rats):
                bbmod.status_variant = 'degraded'
                affected_bbmods.add(bbmod)

        return list(affected_bbmods)

    def _get_affected_rmods(self, affected_bbmods):

        if self.reset_type == 'soft':  # Soft RAT reset shouldn't affect RMODs
            return []

        affected_rmods = set()
        for bbmod in affected_bbmods:
            affected_bbmod_ports = []
            for soc in bbmod.socs_info:
                if self.reset_rat in soc['configured_rats']:
                    affected_bbmod_ports.extend(soc['ports'])

            for port in bbmod.connected_ports:
                if any([port.link_mode['synchronization'], port.link_mode['configuration']]) and \
                        port.number in affected_bbmod_ports:
                    rmod = port.connected_rmod
                    rmod.status_variant = 'disabled'
                    affected_rmods.add(rmod)

        return list(affected_rmods)

    def _get_affected_cells(self, affected_bbmods, affected_rmods):

        affected_cells = set()
        all_cells = set(self._get_all_cells())

        affected_cells.update(self._get_affected_cells_from_bbmods(affected_bbmods, all_cells))
        affected_cells.update(self._get_affected_cells_from_rmods(affected_rmods))
        affected_cells.update(self._get_affected_cells_from_rat_reset(all_cells, affected_cells))

        return list(affected_cells)

    def _get_affected_rats(self, affected_cells):

        affected_rats = {}
        remaining_cells_per_rat = deepcopy(self._all_cell_ids_per_rat)

        for cell in affected_cells:
            nr_dss_cell_degrade = (cell.type == 'nr' and cell.dss_mode and cell.status_variant == 'degraded')
            if nr_dss_cell_degrade or cell.status_variant != 'degraded':
                remaining_cells_per_rat[cell.type].remove(cell.configured_id)

        for rat, remaining_cells in remaining_cells_per_rat.items():
            if len(remaining_cells) < len(self._all_cell_ids_per_rat[rat]):
                if not remaining_cells:
                    affected_rats[rat] = 'dedicated_for_rat_reset'
                else:
                    affected_rats[rat] = 'degraded'

        return affected_rats

    def _get_not_affected_bbmods(self):
        if self.reset_type == 'soft':  # Soft RAT reset shouldn't affect BBMODs
            return self._all_bbmods
        return list(set(self._all_bbmods) - set(self.affected_components.get('bbmods', [])))

    def _get_not_affected_rmods(self):
        if self.reset_type == 'soft':  # Soft RAT reset shouldn't affect RMODs
            return self._get_all_rmods()
        return list(set(self._get_all_rmods()) - set(self.affected_components.get('rmods', [])))

    def _get_not_affected_cells(self):
        return list(set(self._get_all_cells()) - set(self.affected_components.get('cells', [])))

    def _get_not_affected_rats(self):
        affected_rats = {rat for rat in self.affected_components['rats']}
        not_affected_rats = set(self._all_cell_ids_per_rat.keys()) - affected_rats
        return {rat: 'enabled' for rat in not_affected_rats}

    def _get_commissioned_bbmods(self, adm_api_bbmods_info):
        return [bbmod_info for bbmod_info in adm_api_bbmods_info if 'configuration' in bbmod_info['id']]

    def _get_affected_cells_from_bbmods(self, affected_bbmods, all_cells):

        affected_cells = set()
        for bbmod in affected_bbmods:
            is_multi_soc = len(bbmod.socs_info) > 1     # In multi SoC, only one cell type per SoC
            for cell in bbmod.deployed_cells:
                cell_obj = self._map_cell_id_to_cell_obj(cell, all_cells)
                if not is_multi_soc or (is_multi_soc and cell_obj.type == self.reset_rat):
                    cell_obj.status_variant = 'dedicated_for_rat_reset'
                    cell_obj.is_callable = False
                    affected_cells.add(cell_obj)

        return affected_cells

    def _get_affected_cells_from_rmods(self, affected_rmods):

        affected_cells = set()
        for rmod in affected_rmods:
            for cell in rmod.cells:
                cell.status_variant = 'dedicated_for_rat_reset'
                cell.is_callable = False
                affected_cells.add(cell)

        return affected_cells

    def _get_affected_cells_from_rat_reset(self, all_cells, affected_cells):

        af_cells = set()
        remaining_cells = all_cells - affected_cells

        for cell in remaining_cells:
            is_nr_sa_nsa_condition = (cell.type == 'nr' and cell.deptype == 'sa+nsa' and self.reset_rat == 'lte')
            is_nr_dss_condition = (cell.dss_mode and (cell.type, self.reset_rat) in {('nr', 'lte')})
            if cell.type == self.reset_rat or is_nr_sa_nsa_condition or is_nr_dss_condition:
                cell.status_variant = 'dedicated_for_rat_reset'
                cell.is_callable = False
                if is_nr_sa_nsa_condition:
                    cell.status_variant = 'degraded'
                    cell.is_callable = True
                elif is_nr_dss_condition:
                    cell.status_variant = 'degraded'
                    cell.is_callable = False

                af_cells.add(cell)

        return af_cells

    def _map_cell_id_to_cell_obj(self, bbmod_cell, all_cells):
        for cell in all_cells:
            if str(cell.configured_id) == str(bbmod_cell['id']) and cell.type == bbmod_cell['type']:
                return cell

    def _update_statuses_after_l3call_prep(self):
        all_cells_per_rat = self._get_all_cells_per_rat()
        self._update_cells_status(all_cells_per_rat)
        self._update_rats_status(all_cells_per_rat)

    def _update_cells_status(self, all_cells_per_rat):
        for rat, cells in all_cells_per_rat.items():
            cell_ids = [cell.configured_id for cell in cells]
            cells_info_statuses = admin_info_model.get_cells_statuses(cell_ids, rat, self._connection_alias)
            for cell in cells:
                cell_statuses = cells_info_statuses[cell.configured_id]
                if cell_statuses['blockingState'].lower() == 'blocked' and \
                        cell.status_variant != 'dedicated_for_rat_reset':
                    cell.status_variant = 'blocked'

    def _update_rats_status(self, all_cells_per_rat):
        del all_cells_per_rat[self.reset_rat]
        for rat, cells in all_cells_per_rat.items():
            if all(cell.status_variant in ('blocked', 'dedicated_for_rat_reset') for cell in cells):
                self._find_and_update_rat_status(rat, 'dedicated_for_rat_reset')
            elif any(cell.status_variant in ('blocked', 'dedicated_for_rat_reset', 'degraded') for cell in cells):
                self._find_and_update_rat_status(rat, 'degraded')

    def _find_and_update_rat_status(self, rat, status):
        affected_rats = self.affected_components['rats']
        not_affected_rats = self.not_affected_components['rats']

        if rat in affected_rats and affected_rats[rat] != 'dedicated_for_rat_reset':
            self.affected_components['rats'][rat] = status
        elif rat in not_affected_rats:
            del self.not_affected_components['rats'][rat]
            self.affected_components['rats'][rat] = status


class _AdminBase:
    """
    Singleton class only for RAT reset environment verifier.
    This class provides a single instance to handle administrative tasks such as retrieving BTS information
    and managing connections. It ensures that only one instance of the class is created and reused throughout
    the Inheritance.

    Attributes:
    _instance (_AdminBase): Single instance of the class.
    _adm (admin): Admin object.
    _connection_alias (str): Alias for the connection to the BTS.
    _bts_response (dict): Response from the api.
    """

    _instance = None
    _adm = None
    _connection_alias = None
    _bts_response = None

    def __new__(cls, *args, **kwargs):
        if cls.__name__ == '_AdminBase' and cls._instance is None:
            cls._instance = super().__new__(cls)
            return cls._instance
        return super().__new__(cls) if cls.__name__ != '_AdminBase' else cls._instance

    def __init__(self, connection_alias=None):
        if _AdminBase._adm is None:
            _AdminBase._adm = admin()

        if _AdminBase._connection_alias is None and connection_alias is None:
            raise ConnectionAliasNotProvided("Connection alias must be provided.")

        _AdminBase._connection_alias = connection_alias or _AdminBase._connection_alias

        if _AdminBase._bts_response is None:
            _AdminBase._bts_response = _AdminBase._adm.get_bts_info(connection=self._connection_alias)

        self._adm = _AdminBase._adm
        self._connection_alias = _AdminBase._connection_alias
        self._admin_bts_info_response = _AdminBase._bts_response

    @classmethod
    def clear(cls):
        cls._instance = None
        cls._adm = None
        cls._connection_alias = None
        cls._bts_response = None


class _Bbmod(_AdminBase):
    def __init__(self, adm_api_bbmod_info, infomodel_bbmods_response):
        super().__init__()
        self._infomodel_bbmods_response = infomodel_bbmods_response
        self.configured_id = adm_api_bbmod_info['id']['configuration'].split('-')[-1]
        self.runtime_id = adm_api_bbmod_info['id']['runtime'].split('-')[-1]
        self.type = adm_api_bbmod_info['productName'].split()[0]
        self.serial_number = adm_api_bbmod_info['serialNumber']
        self.infomodel_names = self._get_infomodel_names()
        self.socs_info = self._get_socs_info()
        self.connected_ports = self._get_connected_ports()
        self.deployed_cells = self._get_deployed_cell_ids()
        self.status_variant = 'online'

    def _get_connected_ports(self):
        """
        Get connected ports on BBMOD.
        :return: Connected ports of the BBMOD.
        :rtype: list of _BbmodPort objects
        """
        ports = []
        for cablink_info in self._admin_bts_info_response['cables']:
            try:
                bbmod_cablink = cablink_info['firstEndPointId']['configuration'].split('/')[-2].split('-')[-1]
                if bbmod_cablink == self.configured_id:
                    ports.append(_BbmodPort(cablink_info))
            except KeyError as e:
                if 'configuration' not in e.args:
                    raise e

        return ports

    def _get_infomodel_names(self):
        """
        Get infomodel 'L' object names for BTS and BBMOD.
        :return: BTS and BBMOD "L" object names in infomodel.
        :rtype: dict
        """
        for bbmod in self._infomodel_bbmods_response:
            if bbmod['parameters']['serialNumber'] == self.serial_number:
                bts_name = bbmod['distName'].split('/')[3]
                bbmod_name = bbmod['distName'].split('/')[-1]
                return {'bts': bts_name, 'bbmod': bbmod_name}

    def _get_socs_info(self):
        """
        Get information about SoC name, ports range, and configured rat.
        :return: SoC information. e.g. [{'name': 'Xeon', 'ports': [1, 2, 3, ...], 'configured_rats': ['nr']}]
        :rtype: list of dict(s)
        """
        socs_with_ports = {
            'ABIA': [{'name': 'Kepler2', 'ports': list(range(1, 7))}],
            'ABIC': [{'name': 'Lionfish_A', 'ports': list(range(1, 7))},
                     {'name': 'Lionfish_B', 'ports': list(range(7, 10))}],
            'ABIL': [{'name': 'Xeon', 'ports': list(range(1, 5))}],
            'ABIN': [{'name': 'Loki', 'ports': list(range(1, 10))}],
            'ABIO': [{'name': 'Loki_A', 'ports': list(range(1, 7))}, {'name': 'Loki_B', 'ports': list(range(7, 10))}],
            'ABIP': [{'name': 'Thor', 'ports': list(range(1, 13))}],
            'ABIQ': [{'name': 'Magni', 'ports': list(range(1, 10))}]
        }
        if socs_with_ports.get(self.type) is None:
            raise BbmodTypeError(f"Unknown BBMOD type: '{self.type}' \n"
                                 "Please update the dictionary with BBMODs to include the new type.")

        bbmod_socs_infomodel = self._get_bbmod_socs_info(socs_with_ports[self.type])

        if len(socs_with_ports[self.type]) > 1:
            for i, soc in enumerate(socs_with_ports[self.type]):
                soc['configured_rats'] = [rat.lower() for rat in bbmod_socs_infomodel[i]['parameters']['rat']]

        else:
            configured_rats = [rat.lower() for bbmod_soc in bbmod_socs_infomodel for rat in
                               bbmod_soc['parameters']['rat']]
            socs_with_ports[self.type][0]['configured_rats'] = list(set(configured_rats))

        return socs_with_ports[self.type]

    def _get_bbmod_socs_info(self, socs_with_ports):
        """
        Get sorted SoC parameters for BBMOD.
        :param socs_with_ports: hardcoded list of.
        :type socs_with_ports: list of dict(s)
        :return: sorted SoC parameters for BBMOD.
        :rtype: sorted list of dict(s)
        """
        socs_names = [soc['name'] for soc in socs_with_ports]
        socs_infomodel = self._adm.get_managed_objects('SOC_L', connection=self._connection_alias)

        bbmod_socs = []
        for soc_info in socs_infomodel:
            if self.infomodel_names['bts'] in soc_info['distName'] and \
                    self.infomodel_names['bbmod'] in soc_info['distName']:
                if any(soc_info['parameters']['hwVariant'] in s for s in socs_names):
                    bbmod_socs.append(soc_info)

        return sorted(bbmod_socs, key=lambda x: x['parameters']['id'])

    def _get_deployed_cell_ids(self):

        cells = self._adm.get_cell_mapping_by_module_id(module_id=f'BBMOD_R-{self.runtime_id}',
                                                        connection=self._connection_alias)
        bbmod_cells = []
        cell_type_mapping = {
            'GNCEL_R': 'gsm',
            'WNCEL_R': 'wcdma',
            'LNCEL_R': 'lte',
            'NRCELL_R': 'nr'
        }

        for cell in cells:
            for prefix, cell_type in cell_type_mapping.items():
                if prefix in cell:
                    cell_id = cell.split('/')[-2 if prefix == 'GNCEL_R' else -1].split('-')[-1]
                    bbmod_cells.append({'id': cell_id, 'type': cell_type})

        return bbmod_cells

    def __eq__(self, other):
        if isinstance(other, _Bbmod):
            return self.configured_id == other.configured_id
        return False

    def __hash__(self):
        return hash(self.configured_id)


class _BbmodPort:
    """
    BBMOD port class only for RAT reset environment verifier.
    """
    def __init__(self, adm_api_port_info):
        self.number = int(adm_api_port_info['firstEndPointId']['configuration'].split('/')[-1].replace('RF', ''))
        self.port_id = adm_api_port_info['firstEndPointId']['configuration'].split('/')[-1]
        self.link_mode = adm_api_port_info['linkMode']
        self.connected_rmod = _Rmod(conf_name=adm_api_port_info['secondEndPointId']['configuration'].split('/')[3])


class _Rmod(_AdminBase):
    """
    RMOD class only for RAT reset environment verifier.
    """
    def __init__(self, conf_name):
        super().__init__()
        self.configured_name = conf_name
        self.adm_api_rmod_info = self._get_admin_api_rmod_info()
        self.configured_id = self.adm_api_rmod_info['id']['configuration'].split('-')[-1]
        self.runtime_id = self.adm_api_rmod_info['id']['runtime'].split('-')[-1]
        self.cells = self._get_rmod_cells()
        self.status_variant = 'online'

    def _get_admin_api_rmod_info(self):
        for rmod_type, rmods in self._admin_bts_info_response['radioModules'].items():
            for rmod in rmods:
                if rmod['id']['configuration'].split('/')[-1] == self.configured_name:
                    return rmod

        raise RmodInfoNotFound(f"RMOD with name {self.configured_name} not found in admin API response.")

    def _get_rmod_cells(self):
        rmod_cells = []
        for cell_type, cells in self._admin_bts_info_response['cells'].items():
            for cell in cells:
                cell_carriers = [carriers for carriers in cell['carrierList']]
                rmod_name_in_carriers = any([
                    self.configured_name == carrier['antennaLineId']['configuration'].split('/')[-2]
                    for carrier in cell_carriers])
                if rmod_name_in_carriers:
                    rmod_cells.append(_Cell(cell_type, cell))
        return rmod_cells

    def __eq__(self, other):
        if isinstance(other, _Rmod):
            return self.configured_id == other.configured_id
        return False

    def __hash__(self):
        return hash(self.configured_id)


class _Cell(_AdminBase):
    """
    Cell class only for RAT reset environment verifier.
    """
    def __init__(self, cell_type, adm_api_cell_info):
        super().__init__()
        self.type = cell_type
        self.webm_name = adm_api_cell_info['id']['configuration'].split('/')[-1]
        self.configured_id = adm_api_cell_info['id']['configuration'].split('-')[-1]
        self.internal_id = adm_api_cell_info['id']['internal'].split('-')[-1]
        self.deptype = (adm_api_cell_info['cellDepType']).lower() if self.type == 'nr' else None
        self.distname = adm_api_cell_info['id']['configuration']
        self.status_variant = 'online'
        self.dss_mode = self._check_if_cell_in_dss_mode()
        self.is_callable = True

    def _check_if_cell_in_dss_mode(self):
        return admin_info_model.get_partner_cell_if_dss_mode(self.configured_id, self.type, self._connection_alias) \
            if self.type in ('nr', 'lte') else False

    def __eq__(self, other):
        if isinstance(other, _Cell):
            return self.type == other.type and self.configured_id == other.configured_id
        return False

    def __hash__(self):
        return hash((self.type, self.configured_id))
